        end2=s.find('--!>', start)
        if end2!=-1 and (end==-1 or end2<end):
            data=s[start:end2]; self.pos=end2+4
        elif end==-1:
            data=s[start:]; self.pos=self.len
        else:
            data=s[start:end]; self.pos=end+3
