        s=self.s
        i=self.pos+1 if is_start else self.pos+2
        start=i
        while i<self.len and s[i] not in ' \t\n\f/>':
            i+=1
        name_raw=s[start:i]
        name=''.join(chr(ord(c)+32) if 'A'<=c<='Z' else ('\uFFFD' if c=='\x00' else c) for c in name_raw)
