                            parts.append(d); i=np
                        elif s[i]=='\x00':
                            parts.append('\uFFFD'); i+=1
                        else:
                            parts.append(s[i]); i+=1
                    value=''.join(parts)
                    if i<self.len:
                        i+=1  # closing quote
                elif i<self.len and s[i]=='>':
                    value=""
                else:
                    parts=[]
                    while i<self.len and s[i] not in ' \t\n\f>':
                        if s[i]=='&':
                            d, np = self._char_ref_from(s, i, in_attr=True)
                            parts.append(d); i=np
                        elif s[i]=='\x00':
                            parts.append('\uFFFD'); i+=1
                        else:
                            parts.append(s[i]); i+=1
